import pytest

from calibration_target import Record

pytestmark = pytest.mark.verification_kind("unit")


@pytest.mark.verifies("TREQ_CALIBRATION_SUMMARY[revision==1]")
def test_record_summary_omits_secret() -> None:
    value = "classified_data"
    record = Record(name="target_a", secret=value, level=0)
    assert record.summary() == {"name": "target_a"}
